&reftitle.description;
public Yaf_Route_Supervar::__construct stringsupervar_name
Yaf_Route_Supervar es similar a Yaf_Route_Static, con la diferencia de que Yaf_Route_Supervar buscará información de ruta en la cadena de consulta, y el parámetro supervar_name es la clave.

&reftitle.parameters;


  supervar_name


    El nombre de la clave

  &reftitle.examples;

   Ejemplo de Yaf_Route_Supervar


<?php
/**
 * Añade una ruta supervar a la pila de rutas de Yaf_Router.
 *
 * Se espera el URI en la variable de consulta indicada a continuación,
 * por ejemplo http://yourdomain.com/index.php?_url=/product/detail/id/10
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("supervar",
    new Yaf_Route_Supervar("_url")
);
?>


   &example.outputs.similar;


/* http://yourdomain.com/index.php?_url=/product/detail/id/10
 * enruta a los siguientes valores:
 */
array(
  "controller" => "product",
  "module"     => "index", //(por omisión)
  "action"     => "detail", //(por omisión)
)

/**
 * y los parámetros de petición:
 */
array(
  "id" => 10
)
